for playlist in playlists:
    playlist_details = apis.spotify.show_playlist(playlist_id=playlist['playlist_id'], access_token=<REDACTED:CREDENTIAL:SHA256=23b242769a7077870d4a1f1ba7fd989efa8ea2bd3c0fc44af084ce0b5500f538>
    if 'songs' in playlist_details:
        for song in playlist_details['songs']:
            all_songs.append(song)
print(f"Found {len(all_songs)} songs across all playlists")

